def env_lines(text):
    result = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue
        if '=' not in stripped:
            raise ValueError(f"Missing '=' in line: {line!r}")
        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError(f"Empty key in line: {line!r}")
        result[key] = value
    return result
```

