def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dicts; treats lists (and other non-dict
    values) atomically. If a key is added or removed entirely, only the parent
    path is returned (no sub-paths).
    """
    result = set()

    def recurse(b, a, prefix):
        for key in set(b) | set(a):
            path = prefix + "." + key if prefix else key
            if key not in b:
                result.add(path)
            elif key not in a:
                result.add(path)
            elif isinstance(b[key], dict) and isinstance(a[key], dict):
                recurse(b[key], a[key], path)
            elif b[key] != a[key]:
                result.add(path)

    recurse(before, after, "")
    return sorted(result)
```

