from copy import deepcopy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    - Overlay values replace base values (including lists, scalars, None).
    - A None value in overlay does NOT delete the key; it sets the value to None.
    - Nested dicts are merged recursively.
    - The result is deep-independent (no shared references with either input).
    """
    result = {}

    for key, value in base.items():
        if key in overlay:
            overlay_value = overlay[key]
            if isinstance(value, dict) and isinstance(overlay_value, dict):
                result[key] = merge(value, overlay_value)
            else:
                result[key] = deepcopy(overlay_value)
        else:
            result[key] = deepcopy(value)

    for key in overlay:
        if key not in base:
            result[key] = deepcopy(overlay[key])

    return result
```

