def pack(items, max_bytes):
    """Greedily pack consecutive items into batches whose total UTF-8 byte size <= max_bytes."""
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    byte_lengths = [len(s.encode("utf-8")) for s in items]

    for i, blen in enumerate(byte_lengths):
        if blen > max_bytes:
            raise ValueError(f"item {i} exceeds max_bytes")

    if not items:
        return []

    batches = []
    current = []
    current_size = 0

    for item, blen in zip(items, byte_lengths):
        if current_size + blen <= max_bytes:
            current.append(item)
            current_size += blen
        else:
            batches.append(current)
            current = [item]
            current_size = blen

    batches.append(current)
    return batches
```

