from collections import deque

def admit(times, limit, window):
    if limit < 1:
        raise ValueError("limit must be >= 1")
    if window < 1:
        raise ValueError("window must be >= 1")

    accepted = deque()
    result = []

    for t in times:
        while accepted and accepted[0] <= t - window:
            accepted.popleft()
        if len(accepted) < limit:
            accepted.append(t)
            result.append(True)
        else:
            result.append(False)

    return result
